import numpy as np
import pandas as pd

df = pd.read_csv('train.csv')
X = df.drop('target', axis=1).values
y = df['target'].values

def build_tree(X, y, depth=0, max_depth=2):
    if depth == max_depth or len(y) < 10 or np.var(y) < 1e-6:
        return {'val': np.mean(y)}

    best_g = 0
    best_split = None
    base_var = np.var(y)

    # Check 5 percentiles for speed
    for i in range(X.shape[1]):
        percentiles = np.percentile(X[:, i], [20, 40, 60, 80])
        for t in percentiles:
            mask = X[:, i] <= t
            if mask.sum() == 0 or (~mask).sum() == 0: continue

            vl = np.var(y[mask])
            vr = np.var(y[~mask])
            g = base_var - (mask.sum() * vl + (~mask).sum() * vr) / len(y)

            if g > best_g:
                best_g = g
                best_split = (i, t, mask)

    if best_g < 1e-5:
        return {'val': np.mean(y)}

    i, t, mask = best_split
    left = build_tree(X[mask], y[mask], depth+1, max_depth)
    right = build_tree(X[~mask], y[~mask], depth+1, max_depth)
    return {'feat': i, 'thresh': t, 'left': left, 'right': right}

def predict_tree(tree, x):
    if 'val' in tree: return tree['val']
    if x[tree['feat']] <= tree['thresh']:
        return predict_tree(tree['left'], x)
    return predict_tree(tree['right'], x)

class GBM:
    def fit(self, X, y):
        self.trees = []
        self.lr = 0.1
        pred = np.zeros(len(y))
        for step in range(20):
            res = y - pred
            tree = build_tree(X, res, max_depth=2)
            p = np.array([predict_tree(tree, x) for x in X])
            pred += self.lr * p
            self.trees.append(tree)
            print(f'step {step} train mse:', np.mean((y - pred)**2))

gbm = GBM()
gbm.fit(X[:1000], y[:1000])
"

